import os
import boto3

def query_documents(payload, config=None):
    config = config or {}
    dynamodb = boto3.resource('dynamodb', region_name=config.get('region_name', 'us-east-1'))
    table_name = config.get('table_name', os.environ.get('DYNAMODB_TABLE_NAME'))
    if not table_name:
        raise ValueError("DynamoDB table name must be provided in config or DYNAMODB_TABLE_NAME environment variable.")
    table = dynamodb.Table(table_name)

    key_condition_expression = payload.get('key_condition_expression')
    filter_expression = payload.get('filter_expression')
    expression_attribute_names = payload.get('expression_attribute_names')
    expression_attribute_values = payload.get('expression_attribute_values')

    query_params = {
        'KeyConditionExpression': key_condition_expression
    }
    if filter_expression:
        query_params['FilterExpression'] = filter_expression
    if expression_attribute_names:
        query_params['ExpressionAttributeNames'] = expression_attribute_names
    if expression_attribute_values:
        query_params['ExpressionAttributeValues'] = expression_attribute_values

    response = table.query(**query_params)
    result = response.get('Items', [])
    return result
